import os
import pandas as pd
import numpy as np
import torch
import random


class Config:
    # ==============================
    # File Paths
    # ==============================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_1")

    # Metadata paths (Generated by the provided script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Raw data paths
    UNICODE_MAP_CSV = os.path.join(INPUT_DIR, "unicode_translation.csv")
    TRAIN_IMGS_DIR = os.path.join(
        INPUT_DIR, "train_images"
    )  # Note: Metadata contains relative paths
    TEST_IMGS_DIR = os.path.join(INPUT_DIR, "test_images")

    # Output paths
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # ==============================
    # Compute & Reproducibility
    # ==============================
    SEED = 42
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    NUM_WORKERS = 4

    # ==============================
    # Hyperparameters
    # ==============================
    # Debugging
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 100  # Number of images to use when debugging

    # Object Detection Model
    DET_BATCH_SIZE = 4  # Cite solution_lesson_node_00007: Reduced batch size for higher update frequency
    DET_LR = 0.005
    DET_MOMENTUM = 0.9
    DET_WEIGHT_DECAY = 0.0005
    DET_EPOCHS = 12

    # Inference
    DET_SCORE_THRESHOLD = 0.4  # Confidence threshold for detections
    DET_NMS_THRESHOLD = 0.3  # Non-Maximum Suppression threshold


def seed_everything(seed=42):
    """Sets the seed for reproducibility."""
    random.seed(seed)
    os.environ["PYTHONHASHSEED"] = str(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


def get_label_map(load_cached_data=True):
    """
    Generates or loads the mapping between Unicode labels and Integer IDs.

    Args:
        load_cached_data (bool): If True, attempts to load from cache.

    Returns:
        tuple: (label2id, id2label) dictionaries.
    """
    os.makedirs(Config.CACHE_DIR, exist_ok=True)
    cache_path = os.path.join(Config.CACHE_DIR, "label_map.parquet")

    if load_cached_data and os.path.exists(cache_path):
        try:
            df_map = pd.read_parquet(cache_path)
            label2id = dict(zip(df_map["label"], df_map["id"]))
            id2label = dict(zip(df_map["id"], df_map["label"]))
            return label2id, id2label
        except Exception as e:
            print(f"Failed to load cache: {e}. Recomputing...")

    # Recompute
    # Load training metadata to find all unique labels
    if not os.path.exists(Config.TRAIN_CSV):
        raise FileNotFoundError(f"Training metadata not found at {Config.TRAIN_CSV}")

    df_train = pd.read_csv(Config.TRAIN_CSV)

    unique_labels = set()
    for labels_str in df_train["labels"]:
        if pd.isna(labels_str) or labels_str == "":
            continue
        parts = labels_str.split()
        # Format is: Unicode X Y W H ...
        # We take every 5th element starting from 0
        chars = parts[0::5]
        unique_labels.update(chars)

    # Sort for deterministic ID assignment
    sorted_labels = sorted(list(unique_labels))

    # Create mappings
    label2id = {label: idx for idx, label in enumerate(sorted_labels)}
    id2label = {idx: label for idx, label in enumerate(sorted_labels)}

    # Save to cache
    df_map = pd.DataFrame(
        {"label": list(label2id.keys()), "id": list(label2id.values())}
    )
    df_map.to_parquet(cache_path, index=False)

    return label2id, id2label


# Set seed immediately upon import to ensure consistency
seed_everything(Config.SEED)
